/// A headless journey runner: render [current] however you like, then call [complete] with what the
/// customer did. It records document and consent evidence, stores fields, prefills, starts hosted actions
/// (returning where to send the customer) and follows the journey's branches.
class JourneyRunner {
  final MyntClient client;
  final Map<String, dynamic> journey;
  final String _product;
  final Map<String, Map<String, dynamic>> _steps;
  Map<String, dynamic>? current;

  JourneyRunner._(this.client, this.journey, this._product, this._steps, this.current);

  static Future<JourneyRunner> start(MyntClient client, String journeyId) async {
    final journey = await client.journey(journeyId);
    final list = (journey['steps'] as List<dynamic>? ?? const []).cast<Map<String, dynamic>>();
    final product = (journey['built_on'] as Map<String, dynamic>)['product_id'] as String;
    return JourneyRunner._(client, journey, product, {for (final s in list) s['id'] as String: s}, list.isEmpty ? null : list.first);
  }

  bool get done {
    final s = current;
    if (s == null) return true;
    return !s.containsKey('next') && !s.containsKey('on') && !s.containsKey('action') && !s.containsKey('capture_consent') && !s.containsKey('await_event');
  }

  void _go(String? id) => current = id == null ? null : _steps[id];

  String? _branch(Map<String, dynamic> step, String? outcome) {
    final on = step['on'] as Map<String, dynamic>?;
    if (outcome != null && on != null && on[outcome] is String) return on[outcome] as String;
    return step['next'] as String?;
  }

  /// Completes the current step; for a hosted action, returns where to send the customer.
  Future<String?> complete([StepInput input = const StepInput()]) async {
    final step = current;
    if (step == null) throw StateError('The journey has ended');
    final purpose = step['capture_consent'] as String?;
    if (purpose != null) {
      final text = input.consentText;
      if (text == null) throw ArgumentError('Pass the consent wording the customer agreed to');
      await client.giveConsent(_product, purpose, text);
      _go(_branch(step, null));
      return null;
    }
    final action = step['action'] as String?;
    if (action != null) {
      if (input.outcome != null) {
        _go(_branch(step, input.outcome));
        return null;
      }
      return (await client.startAction(_product, action))['redirect_url'] as String?;
    }
    if (step.containsKey('await_event')) {
      _go(_branch(step, input.outcome));
      return null;
    }
    final elements = (step['screen'] as List<dynamic>? ?? const []).cast<Map<String, dynamic>>();
    for (final e in elements.where((e) => e['type'] == 'disclosure')) {
      final document = e['document'] as String;
      final text = input.documents[document];
      if (text == null) throw ArgumentError('Pass the text shown for document $document');
      await client.documentShown(_product, document, text);
    }
    final fields = elements.where((e) => e['type'] == 'field').toList();
    for (final source in const ['typed', 'secure_field', 'document_upload']) {
