        for (final f in fields)
          if ((f['capture'] as String? ?? 'typed') == source && input.fields.containsKey(f['field'])) f['field'] as String: input.fields[f['field']]!,
      };
      if (values.isNotEmpty) await client.saveFields(_product, values, source: source);
    }
    for (final source in const ['account_aggregator', 'digilocker', 'ckyc']) {
      final wanted = [
